#!/usr/bin/env bash
# Some portions generated by Codex. Untimed route/hit qualification, no timing claims.
set -euo pipefail
cd "$(dirname "$0")/../../.."
: "${CP_A:?}" "${CP_B:?}" "${LOCK:?}"
JAVA=${JAVA:-../toolchain/jdk-25.0.5+8/bin/java}
JAVAC=${JAVAC:-../toolchain/jdk-25.0.5+8/bin/javac}
OUT=${OUT:-experiments/threadlocal-audit/record-cancellation/diagnostics-01}
if [[ -e $OUT ]]; then echo "Refuse existing output $OUT" >&2; exit 2; fi
mkdir -p "$OUT/harness"
exec 9>"$LOCK"; flock 9
"$JAVAC" -cp "$CP_B" -d "$OUT/harness" experiments/threadlocal-audit/record-cancellation/RecordCancellationQueryBenchmark.java
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
FLAGS+=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640 -Drdf4j.lmdb.recordCancellation.trace=true)
printf 'cell\tarm\tstatus\n' > "$OUT/status.tsv"
for kind in broad scan probes; do
 shape=narrow; adjacency=true
 [[ $kind == scan ]] && shape=scan
 [[ $kind != broad ]] && adjacency=false
 for regime in regular interpreted janino; do
  for arm in A B0 B1; do
   cp=$CP_B; on=false; [[ $arm == A ]] && cp=$CP_A; [[ $arm == B1 ]] && on=true
   log="$OUT/$kind-$regime-$arm.log"
   # A legacy runtime may not expose metrics; missing fields are marked unavailable, never treated as measured zero.
   if "$JAVA" --enable-native-access=ALL-UNNAMED -Xms1g -Xmx3g "${FLAGS[@]}" \
    "-Drdf4j.lmdb.recordCancellation.owned=$on" "-Daudit.regime=$regime" "-Daudit.shape=$shape" \
    "-Daudit.adjacency=$adjacency" -Doverlay.benchmark.warmups=0 -cp "$OUT/harness:$cp" \
    org.eclipse.rdf4j.sail.lmdb.evaluation.RecordCancellationQueryBenchmark "${GROUPS_COUNT:-2}" 10 1 true > "$log" 2>&1; then
    printf '%s\t%s\tPASS\n' "$kind-$regime" "$arm" >> "$OUT/status.tsv"
   else
    printf '%s\t%s\tFAIL_OR_UNSUPPORTED\n' "$kind-$regime" "$arm" >> "$OUT/status.tsv"
   fi
  done
 done
done
python3 experiments/threadlocal-audit/record-cancellation/summarize-diagnostics.py "$OUT" > "$OUT/summary.json"
